(()=>{const zh=document.documentElement.lang.startsWith('zh'),keys=['logKd','enthalpy','protein'],defaults={logKd:0,enthalpy:-40,protein:20},get=k=>document.getElementById('C05-'+k);let state={};function update(){const log=+get('logKd').value,kd=10**log,h=+get('enthalpy').value,m=+get('protein').value;let mt=m,lt=0,b=0,rows=[];for(let j=0;j<25;j++){mt*=.99;lt=.99*lt+.15*m;let z=mt+lt+kd,bb=2*mt*lt/(z+Math.sqrt(z*z-4*mt*lt)),q=.2*h*(bb-.99*b);rows.push([lt/mt,q/(.03*m),q]);b=bb;}state={logKd:log,enthalpy:h,protein:m,c_value:m/kd,free_energy_kJ_per_mol:.00831446261815324*298.15*Math.log(kd*1e-6),first_heat_uJ:rows[0][2],last_heat_uJ:rows[24][2],final_protein_uM:mt};keys.forEach(k=>get(k+'-value').textContent=(+get(k).value).toFixed(2));get('result').textContent='Kᴅ = '+kd.toFixed(3)+' μM; c = '+state.c_value.toFixed(2)+'; ΔG° = '+state.free_energy_kJ_per_mol.toFixed(2)+' kJ/mol; '+(zh?'第一针结合热：':'First binding heat: ')+state.first_heat_uJ.toFixed(3)+' μJ';const X=x=>80+x/4.5*630,Y=y=>305-(y+65)/90*250;let out='<rect width="760" height="380" fill="#fcfbf7"/><path d="M80 45V305H710" fill="none" stroke="#61758a"/>';for(const y of [-60,-40,-20,0,20])out+='<line x1="80" x2="710" y1="'+Y(y)+'" y2="'+Y(y)+'" stroke="#dce3e5"/><text x="70" y="'+(Y(y)+4)+'" font-size="12" text-anchor="end">'+y+'</text>';for(let x=0;x<=4;x++)out+='<text x="'+X(x)+'" y="327" text-anchor="middle" font-size="12">'+x+'</text>';out+='<path d="'+rows.map((r,i)=>(i?'L':'M')+X(r[0]).toFixed(2)+' '+Y(r[1]).toFixed(2)).join(' ')+'" fill="none" stroke="#167d9a" stroke-width="2.5"/>';rows.forEach(r=>out+='<circle cx="'+X(r[0])+'" cy="'+Y(r[1])+'" r="3.4" fill="#d35f47"/>');out+='<text x="85" y="25" font-size="13">'+(zh?'热量 / 加入配体量 / kJ/mol':'Heat / injected ligand amount / kJ/mol')+'</text><text x="395" y="355" text-anchor="middle" font-size="13">'+(zh?'池内总配体 / 总蛋白质':'Cell total ligand / total protein')+'</text>';get('plot').innerHTML=out;}function set(p){keys.forEach(k=>{if(p[k]!==undefined){const e=get(k);e.value=Math.max(+e.min,Math.min(+e.max,+p[k]));}});update();}keys.forEach(k=>get(k).addEventListener('input',update));get('reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...state}),reset:()=>set(defaults)};update();})();
